require dirname(__DIR__).'/includes/bootstrap.php';require_permission('reports.export');ensure_runtime_schema();$from=(string)($_GET['from']??date('Y-m-d',strtotime('-30 days')));$to=(string)($_GET['to']??date('Y-m-d'));header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="registration-counts-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','Customers','Drivers','Combined']);$q=db()->prepare('SELECT activity_date,customers_registered,drivers_registered FROM daily_growth_counts WHERE activity_date BETWEEN ? AND ? ORDER BY activity_date');$q->execute([$from,$to]);foreach($q as $r)fputcsv($out,[$r['activity_date'],$r['customers_registered'],$r['drivers_registered'],(int)$r['customers_registered']+(int)$r['drivers_registered']]);fclose($out);exit;
